    (void)(kspl_std_str_Str_builder_s(kspl_put_std_str_Str_builder_Ptr_std_strfmt_Int_fmt(kspl_std_str_Str_builder_s(&final_msg, KSPL_STR(std_lang_Slice_U8, "Final Global Heap : ")), kspl_Sz_fmt_spec(heap_used, (Sz)0, false, true)), KSPL_STR(std_lang_Slice_U8, " bytes (Should be 0 - memory leak)\n")));
